content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-001

=== 用户原始指令 (query.txt) ===
给整个免打扰卡，有个按钮能开关，点一下跳到系统设置，顺便看看天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给整个免打扰卡，有个按钮能开关，点一下跳到系统设置，顺便看看天气",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "statusText": {
        "type": "string",
        "description": "免打扰或专注模式当前状态文本。",
        "sampleValue": "免打扰已开启"
      },
      "caption": {
        "type": "string",
        "description": "免打扰模式的简短辅助说明。",
        "sampleValue": "来电和通知保持静默"
      },
      "buttonLabel": {
        "type": "string",
        "description": "进入系统设置调整免打扰开关的按钮文案。",
        "sampleValue": "开关设置"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "青浦"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级。",
            "sampleValue": "空气优"
          }
        }
      }
    },
    "assets": {
      "focusIcon": {
        "type": "string",
        "description": "专注模式图标素材路径。",
        "sampleValue": "resources/base/media/icon_focus.png"
      },
      "weatherIcon": {
        "type": "string",
        "description": "天气图标素材路径。",
        "sampleValue": "resources/base/media/cloudy.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合用于免打扰或专注状态识别。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合展示多云或普通天气摘要。"
    }
  ]
}

